/* @lc app=leetcode id=2499 lang=kotlin */ class Solution { fun minimumTotalCost(nums1: IntArray, nums2: IntArray): Long = nums1.indices.filter { nums1[it] == nums2[it] }.let { same -> if (same.isEmpty()) 0L else same.groupBy { nums1[it] }.mapValues { it.value.size }.let { freq -> freq.maxByOrNull { it.value }?.let { maxF -> if (maxF.value * 2 <= same.size) same.sumOf { it.toLong() } else (same.sumOf { it.toLong() } + (nums1.indices.filter { i -> nums1[i] != nums2[i] && nums1[i] != maxF.key && nums2[i] != maxF.key }.take(maxF.value * 2 - same.size).let { extra -> if (extra.size < maxF.value * 2 - same.size) -2e15.toLong() else extra.sumOf { it.toLong() } })).let { if (it < 0) -1L else it } } ?: same.sumOf { it.toLong() } } } }